<?php use App\Support\App;$u=App::requireAuth();$title='My Account';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><div><h1 class="page-title">My Account</h1><p class="page-sub">Kelola profil, nomor WhatsApp dan keamanan akun.</p></div><div class="grid lg:grid-cols-2 gap-5 mt-6"><form id="profile" class="saas-card p-6 space-y-4"><div><b>Profile information</b><p class="text-sm text-zinc-500">Informasi akun utama Anda.</p></div><label class="text-sm font-semibold">Name<input class="field mt-2" name="name" value="<?=htmlspecialchars($u['name'])?>" required></label><label class="text-sm font-semibold">Email<input class="field mt-2 opacity-70" value="<?=htmlspecialchars($u['email'])?>" disabled></label><label class="text-sm font-semibold">WhatsApp / Phone<input class="field mt-2" name="phone" inputmode="tel" placeholder="62812xxxxxxxx" value="<?=htmlspecialchars($u['phone']??'')?>" required></label><div class="flex gap-2"><span class="badge"><?=htmlspecialchars($u['level_code']??'user')?></span><span class="badge"><?=htmlspecialchars($u['status'])?></span></div><button class="btn btn-dark">Save profile</button></form><form id="pass" class="saas-card p-6 space-y-4"><div><b>Security</b><p class="text-sm text-zinc-500">Ganti password akun.</p></div><input class="field" type="password" name="current_password" placeholder="Current password" required><input class="field" type="password" minlength="8" name="new_password" placeholder="New password · min 8 characters" required><button class="btn">Change password</button></form></div><script>for(const [f,url] of [[profile,'/api/account'],[pass,'/api/account/password']])f.onsubmit=async e=>{e.preventDefault();let r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':'<?=App::csrf()?>'},body:JSON.stringify(Object.fromEntries(new FormData(f)))}),j=await r.json();Swal.fire(j.ok?'Saved':'Error',j.message,j.ok?'success':'error')}</script><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>